function fail(e){notify(e?.message||t('error'));}
async function query(q){const r=await q;if(r.error)throw r.error;return r.data;}
const rpc=(name,data={})=>{if(!db)throw Error(t('connect'));return query(db.rpc(name,data));};
const table=(name,cols='*')=>{if(!db)throw Error(t('connect'));return db.from(name).select(cols);};
const need=()=>{if(!db)throw Error(t('connect'));if(!user){location.href=`giris.html?next=${encodeURIComponent(location.pathname+location.search)}`;throw Error(t('needLogin'));}};
const safeAction=fn=>async e=>{e?.preventDefault();const b=e?.submitter;if(b)b.disabled=true;try{await fn(e);}catch(err){fail(err);}finally{if(b)b.disabled=false;}};
const pageHead=(k,extra='')=>`<div class="page-head"><h1>${t(k)}</h1>${extra}</div>`;
const box=(title,body)=>`<section class="panel"><h2>${t(title)}</h2>${body}</section>`;
const empty=()=>`<p class="empty">${t('empty')}</p>`;
const loginPrompt=()=>`<p class="empty">${t(db?'needLogin':'connect')} <a href="giris.html?next=${encodeURIComponent(location.pathname+location.search)}">${t('signin')}</a></p>`;
const label=(k,input)=>`<label>${t(k)}${input}</label>`;
const inp=(name,type='text',value='',extra='')=>`<input name="${name}" type="${type}" value="${esc(value)}" ${extra}>`;
const opts=(list,val='',any=true)=>`${any?`<option value="">${t('any')}</option>`:''}${list.map(x=>{const [v,k]=Array.isArray(x)?x:[x,x];return `<option value="${esc(v)}" ${String(v)===String(val)?'selected':''}>${esc(D[k]?t(k):k)}</option>`;}).join('')}`;
const select=(name,list,val='',any=true)=>`<select name="${name}">${opts(list,val,any)}</select>`;
const check=(name,k,checked=false)=>`<label class="check"><input type="checkbox" name="${name}" ${checked?'checked':''}>${t(k)}</label>`;
const button=(k,id='',cls='btn')=>`<button class="${cls}" ${id?`id="${id}"`:''}>${t(k)}</button>`;
function guard(form,fn){form.dataset.start=Date.now();form.insertAdjacentHTML('beforeend','<input class="trap" name="website_check" tabindex="-1" autocomplete="off" aria-hidden="true">');form.onsubmit=safeAction(async e=>{if(form.website_check.value||Date.now()-Number(form.dataset.start)<700)throw Error(t('invalid'));await fn(new FormData(form),e);});}
function meta(title,desc){document.title=`${title} | BETA.CAR`;for(const s of ['meta[name=description]','meta[property="og:description"]'])$(s)?.setAttribute('content',desc||title);$('meta[property="og:title"]')?.setAttribute('content',document.title);let c=$('link[rel=canonical]');if(!c){c=document.createElement('link');c.rel='canonical';document.head.append(c);}c.href=location.href.split('#')[0];for(const [name,value] of [['og:url',c.href],['og:image',new URL('logo.png',location.href).href]]){let n=$(`meta[property="${name}"]`);if(!n){n=document.createElement('meta');n.setAttribute('property',name);document.head.append(n);}n.content=value;}}
async function clip(s){try{await navigator.clipboard.writeText(s);notify(t('success'));}catch{notify(s);}}
async function signed(bucket,file){if(!file)return '';const r=await db.storage.from(bucket).createSignedUrl(file,120);if(r.error)throw r.error;return r.data.signedUrl;}
async function uploadFile(bucket,file,dir,max=10485760){need();if(!file||file.size>max||!['image/jpeg','image/png','image/webp',...(bucket==='ilanlar'||bucket==='firmalar'?[]:['application/pdf'])].includes(file.type))throw Error(t('fileError'));const ext=file.type==='application/pdf'?'pdf':file.type==='image/png'?'png':file.type==='image/webp'?'webp':'jpg';const name=`${user.id}/${dir?dir+'/':''}${crypto.randomUUID()}.${ext}`;const r=await db.storage.from(bucket).upload(name,file,{contentType:file.type,upsert:false});if(r.error)throw r.error;return bucket==='ilanlar'||bucket==='firmalar'?db.storage.from(bucket).getPublicUrl(name).data.publicUrl:name;}
const safety=()=>`<aside class="warning"><p>${t('safety')}</p><p>${t('ibanWarning')}</p></aside>`;
const money=(n,c='GBP')=>n==null?t('priceContact'):`${number(n)} ${esc(c)}`;
function currencyTools(){return label('currency',select('display_currency',[['','nativePrice'],...['GBP','EUR','USD','TL'].filter(c=>settings.kurlar?.[c]>0)],read('bc-currency',''),false));}
function displayPrice(c){const to=read('bc-currency',''),rates=settings.kurlar||{};return to&&to!==c.para_birimi&&rates[to]>0&&rates[c.para_birimi]>0&&c.fiyat!=null?`${t('approx')} ${money(Math.round(c.fiyat/rates[c.para_birimi]*rates[to]),to)}`:price(c);}
function currencyBind(){const s=$('[name=display_currency]');if(s)s.onchange=()=>{write('bc-currency',s.value);$$('.listing').forEach(n=>{const c=listed.find(c=>c.id===$('[data-fav]',n)?.dataset.fav);if(c)$('.price',n).textContent=displayPrice(c);});};}
