const bodyStates=['','orijinal','lokal_boyali','boyali','degisen','hasarli'],bodyLabels=['unknown','originalState','localPaint','paintState','replaceState','damageState'];
const bodyName=s=>t(bodyLabels[Math.max(0,bodyStates.indexOf(s))]);
function bodySvg(data={},edit=false){return `<svg class="body-svg" viewBox="0 0 240 390" role="group" aria-label="${t('bodyBox')}"><defs><pattern id="damage-pattern" width="7" height="7" patternUnits="userSpaceOnUse"><path fill="#70232a" d="M0 0h7v7H0z"/><path stroke="#e8949b" d="M-1 1l7 7M3-3l7 7"/></pattern></defs><path fill="#111820" stroke="#46546a" d="M70 18Q120 0 170 18L206 63V325L173 365Q120 388 67 365L34 325V63Z"/><path fill="#22314b" stroke="#526079" d="M77 124Q120 110 163 124L159 149Q120 139 81 149ZM81 248Q120 260 159 248L163 273Q120 286 77 273Z"/>${partsDef.map(([id,tr,en,d])=>`<path class="body-part state-${data[id]||'none'}" d="${d}" data-part="${id}" tabindex="0" role="${edit?'button':'img'}" aria-label="${esc(lang==='en'?en:tr)}: ${bodyName(data[id]||'')}" ${edit?'':'aria-roledescription="panel"'}><title>${esc(lang==='en'?en:tr)}: ${bodyName(data[id]||'')}</title></path>`).join('')}</svg>`;}
function bodyBox(data={},report){const summary=partsDef.every(p=>data[p[0]]==='orijinal')?t('allOriginalText'):!Object.keys(data).length?t('noBody'):bodyStates.slice(1).filter(s=>s!=='orijinal').map(s=>{const n=Object.values(data).filter(x=>x===s).length;return n?`${n} ${bodyName(s).toLowerCase()}`:'';}).filter(Boolean).join(', ');return box('bodyBox',`<div class="body-layout">${bodySvg(data)}<div><p class="body-summary">${esc(summary||t('unknown'))}</p>${bodyStates.map((s,i)=>{const names=partsDef.filter(p=>(data[p[0]]||'')===s).map(p=>lang==='en'?p[2]:p[1]);return names.length?`<p class="legend"><span class="swatch state-${s||'none'}"></span><strong>${t(bodyLabels[i])}</strong><span>${esc(names.join(', '))}</span></p>`:'';}).join('')}<p data-part-label aria-live="polite"></p><small>${t('declaration')}</small>${report?`<p>${esc(report.firma)} · ${esc(report.tarih)}</p><button class="text-btn" data-report="${esc(report.dosya)}">${t('report')}</button>`:''}</div></div>`);}
function bindPanels(){$$('.body-layout .body-part').forEach(p=>{const show=()=>{const label=$('[data-part-label]',p.closest('.body-layout'));if(label)label.textContent=p.getAttribute('aria-label');};p.onclick=show;p.onfocus=show;p.onmouseenter=show;});}
function equipmentBox(ids=[]){return box('equipment',groups.map((g,i)=>`<details ${i<2?'open':''}><summary>${groupName(g)}</summary><p>${eqs.filter(e=>e.grup===g&&ids.includes(e.id)).map(e=>`<abbr title="${esc(({ABS:t('absTip'),ESP:t('espTip'),AEB:t('aebTip')})[e.ad]||e.ad)}">${esc(lang==='en'?e.ad_en:e.ad)}</abbr>`).join(', ')||`<span class="muted">${t('unknown')}</span>`}</p></details>`).join(''));}
function equipmentEdit(ids=[],tip=''){return `<input id="equipment-search" type="search" placeholder="${t('searchEquipment')}">${groups.map(g=>`<details open><summary>${groupName(g)}</summary><button type="button" class="text-btn" data-select-group="${esc(g)}">${t('selectAll')}</button><div class="checks">${eqs.filter(e=>e.grup===g&&(!tip||e.arac_tipi.includes(tip))).map(e=>`<label class="check" data-equipment-label><input type="checkbox" name="donanim" value="${e.id}" ${ids.includes(e.id)?'checked':''}>${esc(lang==='en'?e.ad_en:e.ad)}</label>`).join('')}</div></details>`).join('')}`;}
function bindEquipment(){const s=$('#equipment-search');if(s)s.oninput=()=>$$('[data-equipment-label]').forEach(l=>l.hidden=!key(l.textContent).includes(key(s.value)));$$('[data-select-group]').forEach(b=>b.onclick=()=>{const checks=$$('input[type=checkbox]',b.closest('details'));const value=!checks.every(c=>c.checked);checks.forEach(c=>c.checked=value);});}
async function route(){const id=++routeId,page=document.body.dataset.page;$('#main').className='wrap page';const map={list:listPage,detail:detailPage,compare:comparePage,model:()=>valuationPage(true),valuation:()=>valuationPage(false),login:loginPage,account:accountPage,editor:editorPage,photos:photosPage,messages:messagesPage,wanted:wantedPage,packages:packagesPage,firms:firmsPage,firm:firmPage,posts:postsPage,legal:legalPage,admin:adminPage};await map[page]?.(id);}
function readFilter(form,values){const f=new FormData(form),p={...Object.fromEntries(f),...values()};p.donanim=f.getAll('donanim').map(Number);p.detay={};for(const k of Object.keys(p)){if(k.startsWith('d_')){p.detay[k.slice(2)]=p[k]==='on'?'true':p[k];delete p[k];}if(p[k]===''||k==='website_check')delete p[k];}if(!p.ekspertizli)delete p.ekspertizli;else p.ekspertizli='true';return p;}
