async function valuationPage(modelOnly){meta(t(modelOnly?'modelTitle':'valuationTitle'));$('#main').innerHTML=pageHead(modelOnly?'modelTitle':'valuationTitle')+`<form id="valuation" class="panel">${vehicleForm()}<div class="fields">${label('km',inp('km','number','','min="0"'))}${label('fuel',select('yakit',['petrol','diesel','hybrid','mild','plugin','electric']))}${label('gear',select('vites',['automatic','manual']))}${label('currency',select('para_birimi',['GBP','EUR','USD','TL'],'GBP',false))}</div>${button('calculate')}</form><div id="valuation-result"></div>`;const form=$('#valuation'),values=bindVehicles(form);guard(form,async()=>{const v=values();if(!v.model)throw Error(t('invalid'));const [m,rows]=await Promise.all([rpc('model_ozeti',{p_model:Number(v.model),p_yil:v.yil?Number(v.yil):null,p_km:!modelOnly&&form.km.value?Number(form.km.value):null,p_yakit:!modelOnly?form.yakit.value:null,p_vites:!modelOnly?form.vites.value:null,p_para:form.para_birimi.value}),rpc('ilan_ara',{p:{...v,para_birimi:form.para_birimi.value}})]);const lower=modelOnly?m.en_dusuk:m.adet>=5?m.alt:null,upper=modelOnly?m.en_yuksek:m.adet>=5?m.ust:null;
 $('#valuation-result').innerHTML=box('estimate',m&&lower?`<strong class="detail-price">${money(lower,form.para_birimi.value)} – ${money(upper,form.para_birimi.value)}</strong><dl class="spec-table"><div><dt>${t('average')}</dt><dd>${money(m.ortalama,form.para_birimi.value)}</dd></div><div><dt>${t('count')}</dt><dd>${m.adet}</dd></div></dl><div class="distribution"><h3>${t('distribution')}</h3>${(m.dagilim||[]).map(([i,n])=>`<label>${money(Math.round(Number(m.en_dusuk)+(Number(m.en_yuksek)-Number(m.en_dusuk))*i/5),form.para_birimi.value)}<meter min="0" max="${m.adet}" value="${n}"></meter><span>${n}</span></label>`).join('')}</div>`:`<p>${t('insufficient')}</p>`)+`<a class="btn" id="sell-estimate" href="ilan-ver.html">${t('sellMine')}</a><div class="listing-list">${rows.ilanlar.map(card).join('')}</div>`;$('#sell-estimate').onclick=()=>write('bc-valuation',{...v,km:form.km.value,yakit:form.yakit.value,vites:form.vites.value});if(modelOnly)meta(`${form.marka.value} ${form.model.value} · ${t('modelTitle')}`,`${form.marka.value} ${form.model.value}: ${rows.toplam} ${t('resultCount')}`);bindCards();});
 const m=lex.modeller.find(x=>String(x[0])===params.get('model')),b=lex.markalar.find(x=>x[0]===m?.[1]);if(b&&m){form.marka.value=b[1];form.marka.dispatchEvent(new Event('input'));form.model.value=m[2];form.model.dispatchEvent(new Event('input'));form.dataset.start=Date.now()-1000;form.requestSubmit();}
}
function nextUrl(){const value=params.get('next')||'hesabim.html';try{const u=new URL(value,location.href);return u.origin===location.origin&&u.pathname.endsWith('.html')?u.href:new URL('hesabim.html',location.href).href;}catch{return 'hesabim.html';}}
async function loginPage(){meta(t('signin'));let mode=params.get('mode')||'signin';function draw(){$('#main').innerHTML=pageHead('signin')+`<div class="auth panel"><div class="tabs">${['signin','register','reset'].map(k=>`<button data-auth="${k}" class="${mode===k?'active':''}">${t(k)}</button>`).join('')}</div><form id="auth-form">${mode==='register'?`${label('name',inp('ad','text','','required maxlength="100"'))}${label('type',select('tip',[['bireysel','personal'],['kurumsal','business']],'bireysel',false))}<div id="company-fields" hidden>${label('companyName',inp('firma','text','','maxlength="140"'))}${label('companyType',select('tur',['galeri','yetkili_satici','parca_tedarikcisi','ekspertiz_merkezi'],'galeri',false))}${label('tax',inp('vergi','text','','maxlength="40"'))}</div>`:''}${mode!=='password'?label('email',inp('email','email','','required autocomplete="email"')):''}${mode!=='reset'?label('password',inp('password','password','','required minlength="10" autocomplete="'+(mode==='signin'?'current-password':'new-password')+'"')):''}${mode==='register'?`<label class="check"><input type="checkbox" required>${t('acceptTerms')}</label><div class="actions"><a href="sayfa.html?s=bireysel-uye-sozlesmesi">${t('personalTerms')}</a><a href="sayfa.html?s=kurumsal-uye-sozlesmesi">${t('businessTerms')}</a><a href="sayfa.html?s=gizlilik-politikasi">${t('privacy')}</a></div>`:''}${button(mode==='password'?'changePassword':mode)}</form></div>`;$$('[data-auth]').forEach(b=>b.onclick=()=>{mode=b.dataset.auth;draw();});const f=$('#auth-form');if(f.tip)f.tip.onchange=()=>{$('#company-fields').hidden=f.tip.value!=='kurumsal';f.firma.required=f.tip.value==='kurumsal';};guard(f,async data=>{if(!db)throw Error(t('connect'));let r;if(mode==='signin'){r=await db.auth.signInWithPassword({email:data.get('email'),password:data.get('password')});if(r.error)throw r.error;location.href=nextUrl();}else if(mode==='register'){r=await db.auth.signUp({email:data.get('email'),password:data.get('password'),options:{emailRedirectTo:new URL('hesabim.html',location.href).href,data:{ad:data.get('ad'),tip:data.get('tip')}}});if(r.error)throw r.error;if(data.get('tip')==='kurumsal')write('bc-company',{email:data.get('email'),ad:data.get('firma'),tur:data.get('tur'),vergi:data.get('vergi')});notify(t('confirmEmail'));}else if(mode==='reset'){r=await db.auth.resetPasswordForEmail(data.get('email'),{redirectTo:new URL('giris.html?mode=password',location.href).href});if(r.error)throw r.error;notify(t('resetSent'));}else{r=await db.auth.updateUser({password:data.get('password')});if(r.error)throw r.error;location.href='hesabim.html';}});}draw();}
