function csvParse(text){const rows=[];let row=[],field='',quote=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quote&&text[i+1]==='"'){field+='"';i++;}else quote=!quote;}else if(c===','&&!quote){row.push(field);field='';}else if((c==='\n'||c==='\r')&&!quote){if(c==='\r'&&text[i+1]==='\n')i++;row.push(field);if(row.some(Boolean))rows.push(row);row=[];field='';}else field+=c;}row.push(field);if(row.some(Boolean))rows.push(row);if(quote)throw Error(t('invalid'));return rows;}
function csvDialog(){const d=document.createElement('dialog');d.innerHTML=`<form><h2>${t('csv')}</h2><p>${t('csvHelp')}</p><input name="file" type="file" accept=".csv,text/csv" required>${button('upload')}<button type="button" class="text-btn">${t('cancel')}</button><output></output></form>`;document.body.append(d);$('button[type=button]',d).onclick=()=>d.close();d.onclose=()=>d.remove();guard($('form',d),async f=>{const file=f.get('file');if(file.size>1048576)throw Error(t('fileError'));const [headers,...rows]=csvParse((await file.text()).replace(/^\uFEFF/,''));const allowed=['kategori_id','baslik','marka_id','model_id','yil','km','fiyat','para_birimi','sehir'];if(headers.some(h=>!allowed.includes(h))||rows.length>100)throw Error(t('invalid'));let n=0;for(const row of rows){const data=Object.fromEntries(headers.map((h,i)=>[h,['kategori_id','marka_id','model_id','yil','km','fiyat'].includes(h)?row[i]?Number(row[i]):null:row[i]]));await query(db.from('ilanlar').insert(data));$('output',d).textContent=String(++n);}notify(t('success'));});d.showModal();}
