 async function persist(){need();const d=data();const phone=d.detay.telefon;if(phone)await query(db.from('profil').update({telefon:phone}).eq('id',user.id));delete d.detay.telefon;if(d.baslik.length<5)throw Error(t('invalid'));if(id)await query(db.from('ilanlar').update(d).eq('id',id));else{id=(await query(db.from('ilanlar').insert(d).select('id').single())).id;history.replaceState(null,'',`?id=${id}`);write('bc-draft',id);}await query(db.from('ilan_parca').delete().eq('ilan_id',id));if(Object.keys(parts).length)await query(db.from('ilan_parca').insert(Object.entries(parts).map(([parca,durum])=>({ilan_id:id,parca,durum}))));const chosen=$$('[name=donanim]:checked',form).map(e=>Number(e.value));await query(db.from('ilan_donanim').delete().eq('ilan_id',id));if(chosen.length)await query(db.from('ilan_donanim').insert(chosen.map(donanim_id=>({ilan_id:id,donanim_id}))));const file=form.rapor.files[0];if(file){if(!form.ekspertiz_firma.value||!form.ekspertiz_tarih.value)throw Error(t('invalid'));const dosya=await uploadFile('ekspertiz',file,id);report={ilan_id:id,dosya,firma:form.ekspertiz_firma.value,tarih:form.ekspertiz_tarih.value};await query(db.from('ilan_ekspertiz').upsert(report));form.rapor.value='';}if(values().diger_marka||values().diger_model)await query(db.from('oneriler').insert({tip:form.tip.value||'otomobil',marka:values().diger_marka||form.marka.value,model:values().diger_model||null}));return id;}
