async function resizePhoto(file,watermark=false){if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>31457280)throw Error(t('fileError'));const image=await createImageBitmap(file);if(image.width<640||image.height<480)notify(t('smallPhoto'));const scale=Math.min(1,1920/image.width,1440/image.height),canvas=document.createElement('canvas');canvas.width=Math.round(image.width*scale);canvas.height=Math.round(image.height*scale);const ctx=canvas.getContext('2d');ctx.drawImage(image,0,0,canvas.width,canvas.height);image.close();if(watermark){const logo=new Image();logo.src='logo.png';await logo.decode();const w=Math.min(260,canvas.width*.23),h=w*logo.height/logo.width;ctx.globalAlpha=.8;ctx.drawImage(logo,canvas.width-w-12,canvas.height-h-12,w,h);}const blob=await new Promise(r=>canvas.toBlob(r,'image/jpeg',.84));if(!blob)throw Error(t('fileError'));return new File([blob],'photo.jpg',{type:'image/jpeg'});}
